import { Router } from 'express';
import { prisma } from '../../infrastructure/database/prisma';
const router = Router();
router.get('/', async (_req,res)=>{ const items = await prisma.category.findMany({where:{active:true}}); res.json(items); });
router.get('/:slug', async (req,res)=>{ const item = await prisma.category.findUnique({where:{slug:req.params.slug}}); if(!item)return res.status(404).json({error:'Not found'}); res.json(item); });
export default router;
